// Store each joint value in flow context
flow.set(msg.topic, parseFloat(msg.payload));

// Read all joint values (default = home position)
var j1 = (flow.get('j1') !== undefined) ? flow.get('j1') : 0.0;
var j2 = (flow.get('j2') !== undefined) ? flow.get('j2') : -1.5708;
var j3 = (flow.get('j3') !== undefined) ? flow.get('j3') : -1.5708;
var j4 = (flow.get('j4') !== undefined) ? flow.get('j4') : -3.159;
var j5 = (flow.get('j5') !== undefined) ? flow.get('j5') : 0.0;
var j6 = (flow.get('j6') !== undefined) ? flow.get('j6') : 0.0;

flow.set('joint_values', [j1, j2, j3, j4, j5, j6]);

// Update display labels
var display = '';
display += 'J1: ' + j1.toFixed(4) + ' rad\n';
display += 'J2: ' + j2.toFixed(4) + ' rad\n';
display += 'J3: ' + j3.toFixed(4) + ' rad\n';
display += 'J4: ' + j4.toFixed(4) + ' rad\n';
display += 'J5: ' + j5.toFixed(4) + ' rad\n';
display += 'J6: ' + j6.toFixed(4) + ' rad';

msg.payload = display;
return msg;

// Send zeros as stop (or current position if available)
var currentPositions = flow.get('feedback_positions') || [0,0,0,0,0,0];

var cmd = {
    "op": "publish",
    "topic": "/ur_arm_controller/joint_trajectory",
    "type": "trajectory_msgs/JointTrajectory",
    "msg": {
        "header": { "stamp": { "sec": 0, "nanosec": 0 }, "frame_id": "" },
        "joint_names": [
            "ur5_shoulder_pan_joint",
            "ur5_shoulder_lift_joint",
            "ur5_elbow_joint",
            "ur5_wrist_1_joint",
            "ur5_wrist_2_joint",
            "ur5_wrist_3_joint"
        ],
        "points": [
            {
                "positions": currentPositions,
                "velocities": [0,0,0,0,0,0],
                "accelerations": [],
                "effort": [],
                "time_from_start": { "sec": 0, "nanosec": 100000000 }
            }
        ]
    }
};
msg.payload = JSON.stringify(cmd);
return msg;

