try {
    var data = JSON.parse(msg.payload);
    if (!data.msg || !data.msg.name || !data.msg.position) return null;

    var names = data.msg.name;
    var positions = data.msg.position;

    // Extract UR5 joints only
    var ur5Joints = [
        'ur5_shoulder_pan_joint',
        'ur5_shoulder_lift_joint',
        'ur5_elbow_joint',
        'ur5_wrist_1_joint',
        'ur5_wrist_2_joint',
        'ur5_wrist_3_joint'
    ];

    var result = {};
    for (var i = 0; i < names.length; i++) {
        if (ur5Joints.includes(names[i])) {
            result[names[i]] = parseFloat(positions[i]);
        }
    }

    // Store for STOP function
    if (positions.length >= 6) {
        flow.set('feedback_positions', positions.slice(0, 6));
    }

    var display = '';
    var sliders = [null, null, null, null, null, null];
    var shouldSync = flow.get('sync_sliders_now');

    ur5Joints.forEach(function(jn, idx) {
        var shortName = ['J1','J2','J3','J4','J5','J6'][idx];
        var val = result[jn] || 0.0;
        display += shortName + ': ' + val.toFixed(4) + ' rad\n';
        if (shouldSync) {
            sliders[idx] = {payload: val};
            flow.set('j'+(idx+1), val);
        }
    });

    if (shouldSync) {
        flow.set('joint_values', [result[ur5Joints[0]]||0, result[ur5Joints[1]]||0, result[ur5Joints[2]]||0, result[ur5Joints[3]]||0, result[ur5Joints[4]]||0, result[ur5Joints[5]]||0]);
        flow.set('sync_sliders_now', false);
    }

    msg.payload = display.trim();
    return [msg, sliders[0], sliders[1], sliders[2], sliders[3], sliders[4], sliders[5]];

} catch(e) {
    return null;
}
